-- Run this schema in your Cloudflare D1 database using the D1 Console or Wrangler.
CREATE TABLE IF NOT EXISTS countries (
 id TEXT PRIMARY KEY, continent TEXT NOT NULL, flag TEXT NOT NULL DEFAULT '', name TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','TAKEN','CLOSED')), application_id TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS applications (
 application_id TEXT PRIMARY KEY, submitted_at TEXT NOT NULL DEFAULT (datetime('now')), username TEXT NOT NULL, continent TEXT NOT NULL, country_id TEXT NOT NULL UNIQUE, country_name TEXT NOT NULL, prompt1 TEXT DEFAULT '', prompt2 TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'SUBMITTED', answers_json TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(country_id) REFERENCES countries(id)
);
